  RETURN EXISTS (SELECT 1 FROM auth.users AS account WHERE account.id = p_owner)
    AND NOT EXISTS (SELECT 1 FROM biblib.account_lifecycle AS lifecycle WHERE lifecycle.user_id = p_owner AND lifecycle.state <> 'active');
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  affected integer := 0;
BEGIN
  IF p_state NOT IN ('active', 'blocked') THEN
    RAISE EXCEPTION 'Estado de cuenta no válido' USING ERRCODE = '22023';
  END IF;
  INSERT INTO biblib.account_lifecycle AS lifecycle (user_id, state, changed_at) VALUES (p_owner, p_state, now_at)
  ON CONFLICT (user_id) DO UPDATE SET state = excluded.state, changed_at = excluded.changed_at;
  IF p_state = 'blocked' THEN
    UPDATE biblib.library_jobs AS j
    SET state = 'expired', error_code = 'ACCOUNT_INACTIVE', lease_token = NULL, lease_until = NULL, version = gen_random_uuid(),
      finished_at = now_at, expires_at = now_at + interval '30 days', updated_at = now_at
    WHERE j.user_id = p_owner AND j.state IN ('queued', 'running', 'waiting_retry', 'needs_review', 'paused');
    GET DIAGNOSTICS affected = ROW_COUNT;
  END IF;
  RETURN affected;
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  entry biblib.catalogue_cache%ROWTYPE;
  leased bigint;
BEGIN
  IF p_lease_ms IS NULL OR p_lease_ms NOT BETWEEN 1 AND 600000 THEN
    RAISE EXCEPTION 'Concesión no válida' USING ERRCODE = '22023';
  END IF;
  -- Una entrada ilegible se retira solo si sigue siendo la misma que se leyó.
  IF p_discard_fence IS NOT NULL THEN
    DELETE FROM biblib.catalogue_cache AS c
    WHERE c.provider = p_provider AND c.policy_version = p_policy_version AND c.credential_scope = p_scope
      AND c.schema_version = p_schema_version AND c.operation = p_operation AND c.canonical_key = p_key AND c.fence = p_discard_fence;
  END IF;
  IF p_use_cache THEN
    SELECT * INTO entry FROM biblib.catalogue_cache AS c
    WHERE c.provider = p_provider AND c.policy_version = p_policy_version AND c.credential_scope = p_scope
      AND c.schema_version = p_schema_version AND c.operation = p_operation AND c.canonical_key = p_key;
    IF FOUND AND entry.expires_at > now_at THEN
      RETURN jsonb_build_object('state', 'hit', 'status', entry.status, 'payload', entry.payload, 'fence', entry.fence::text, 'fetchedAt', entry.fetched_at, 'expiresAt', entry.expires_at);
    END IF;
  END IF;
  -- Solo se toma la concesión si no existe o si la anterior caducó (trabajador muerto o tardío).
  INSERT INTO biblib.catalogue_inflight AS f (provider, policy_version, credential_scope, schema_version, operation, canonical_key, fence, lease_expires_at)
  VALUES (p_provider, p_policy_version, p_scope, p_schema_version, p_operation, p_key, nextval('biblib.catalogue_fence_seq'), now_at + p_lease_ms * interval '1 millisecond')
  ON CONFLICT (provider, policy_version, credential_scope, schema_version, operation, canonical_key) DO UPDATE
    SET fence = excluded.fence, lease_expires_at = excluded.lease_expires_at, created_at = now_at
    WHERE f.lease_expires_at <= now_at
  RETURNING f.fence INTO leased;
  IF leased IS NULL THEN
    RETURN jsonb_build_object('state', 'pending');
  END IF;
  -- Otro trabajador pudo publicar entre la lectura y la concesión.
  IF p_use_cache THEN
    SELECT * INTO entry FROM biblib.catalogue_cache AS c
    WHERE c.provider = p_provider AND c.policy_version = p_policy_version AND c.credential_scope = p_scope
      AND c.schema_version = p_schema_version AND c.operation = p_operation AND c.canonical_key = p_key;
    IF FOUND AND entry.expires_at > now_at THEN
      DELETE FROM biblib.catalogue_inflight AS f
      WHERE f.provider = p_provider AND f.policy_version = p_policy_version AND f.credential_scope = p_scope
        AND f.schema_version = p_schema_version AND f.operation = p_operation AND f.canonical_key = p_key AND f.fence = leased;
      RETURN jsonb_build_object('state', 'hit', 'status', entry.status, 'payload', entry.payload, 'fence', entry.fence::text, 'fetchedAt', entry.fetched_at, 'expiresAt', entry.expires_at);
    END IF;
  END IF;
  RETURN jsonb_build_object('state', 'leased', 'fence', leased::text);
END;

DECLARE
  now_at timestamptz := clock_timestamp();
BEGIN
  DELETE FROM biblib.catalogue_inflight AS f
  WHERE f.provider = p_provider AND f.policy_version = p_policy_version AND f.credential_scope = p_scope
    AND f.schema_version = p_schema_version AND f.operation = p_operation AND f.canonical_key = p_key
    AND f.fence = p_fence AND f.lease_expires_at > now_at;
  IF NOT FOUND THEN
    DELETE FROM biblib.catalogue_inflight AS f
    WHERE f.provider = p_provider AND f.policy_version = p_policy_version AND f.credential_scope = p_scope
      AND f.schema_version = p_schema_version AND f.operation = p_operation AND f.canonical_key = p_key AND f.fence = p_fence;
    RETURN 'stale';
  END IF;
  IF p_status IS NULL OR p_status NOT IN ('found', 'notFound') OR p_ttl_ms IS NULL OR p_ttl_ms <= 0 OR p_payload IS NULL THEN
    RETURN 'released';
  END IF;
  INSERT INTO biblib.catalogue_cache AS c (provider, policy_version, credential_scope, schema_version, operation, canonical_key, status, payload, provenance, fence, fetched_at, expires_at)
  VALUES (p_provider, p_policy_version, p_scope, p_schema_version, p_operation, p_key, p_status, p_payload, coalesce(p_provenance, '{}'::jsonb), p_fence, now_at, now_at + least(p_ttl_ms, 86400000) * interval '1 millisecond')
  ON CONFLICT (provider, policy_version, credential_scope, schema_version, operation, canonical_key) DO UPDATE
    SET status = excluded.status, payload = excluded.payload, provenance = excluded.provenance, fence = excluded.fence,
      fetched_at = excluded.fetched_at, expires_at = excluded.expires_at
    WHERE c.fence < excluded.fence;
  IF FOUND THEN
    RETURN 'published';
  END IF;
  RETURN 'stale';
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  removed integer;
  counted integer;
BEGIN
  DELETE FROM biblib.catalogue_cache AS c WHERE c.provider = p_provider
    AND (p_policy_version IS NULL OR c.policy_version <> p_policy_version OR c.schema_version <> p_schema_version OR c.expires_at <= now_at);
  GET DIAGNOSTICS removed = ROW_COUNT;
  DELETE FROM biblib.catalogue_private_cache AS c WHERE c.provider = p_provider
    AND (p_policy_version IS NULL OR c.policy_version <> p_policy_version OR c.schema_version <> p_schema_version OR c.expires_at <= now_at);
  GET DIAGNOSTICS counted = ROW_COUNT;
  removed := removed + counted;
  DELETE FROM biblib.catalogue_inflight AS f WHERE f.provider = p_provider AND f.lease_expires_at <= now_at
    AND (p_policy_version IS NULL OR f.policy_version <> p_policy_version OR f.schema_version <> p_schema_version);
  RETURN removed;
END;

DECLARE
  entry biblib.catalogue_private_cache%ROWTYPE;
BEGIN
  SELECT * INTO entry FROM biblib.catalogue_private_cache AS c
  WHERE c.owner_id = p_owner AND c.provider = p_provider AND c.policy_version = p_policy_version AND c.credential_scope = p_scope
    AND c.schema_version = p_schema_version AND c.operation = p_operation AND c.key_hmac = p_key_hmac AND c.expires_at > clock_timestamp();
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  RETURN jsonb_build_object('status', entry.status, 'payload', entry.payload, 'fetchedAt', entry.fetched_at, 'expiresAt', entry.expires_at);
END;

DECLARE
  now_at timestamptz := clock_timestamp();
BEGIN
  IF p_owner IS NULL OR p_status IS NULL OR p_status NOT IN ('found', 'notFound') OR p_ttl_ms IS NULL OR p_ttl_ms <= 0 OR p_payload IS NULL THEN
    RETURN false;
  END IF;
  DELETE FROM biblib.catalogue_private_cache AS c WHERE c.ctid IN (
    SELECT old.ctid FROM biblib.catalogue_private_cache AS old WHERE old.owner_id = p_owner AND old.expires_at <= now_at LIMIT 100);
  INSERT INTO biblib.catalogue_private_cache AS c (owner_id, provider, policy_version, credential_scope, schema_version, operation, key_hmac, status, payload, fetched_at, expires_at)
  VALUES (p_owner, p_provider, p_policy_version, p_scope, p_schema_version, p_operation, p_key_hmac, p_status, p_payload, now_at, now_at + least(p_ttl_ms, 86400000) * interval '1 millisecond')
  ON CONFLICT (owner_id, provider, policy_version, credential_scope, schema_version, operation, key_hmac) DO UPDATE
    SET status = excluded.status, payload = excluded.payload, fetched_at = excluded.fetched_at, expires_at = excluded.expires_at
    WHERE c.fetched_at <= excluded.fetched_at;
  RETURN true;
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  released biblib.catalogue_quota_reservations%ROWTYPE;
  cooldown timestamptz;
BEGIN
  UPDATE biblib.catalogue_quota_reservations AS r SET released_at = now_at
  WHERE r.id = p_reservation AND r.fence = p_fence AND r.released_at IS NULL
  RETURNING * INTO released;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  IF p_retry_after_ms > 0 THEN
    cooldown := now_at + least(p_retry_after_ms, 3600000) * interval '1 millisecond';
    UPDATE biblib.catalogue_quota_buckets AS b
    SET cooldown_until = greatest(b.cooldown_until, cooldown), next_slot_at = greatest(b.next_slot_at, cooldown), updated_at = now_at
    WHERE b.provider = released.provider AND b.credential_scope = released.credential_scope;
  END IF;
  RETURN true;
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  bucket biblib.catalogue_quota_buckets%ROWTYPE;
  slot timestamptz;
  active integer;
  granted bigint;
  reservation uuid;
BEGIN
  IF p_purpose IS NULL OR p_purpose NOT IN ('interactive', 'batch') OR p_interval_ms NOT BETWEEN 1 AND 3600000
    OR p_horizon_ms NOT BETWEEN 0 AND 60000 OR p_owner_cap NOT BETWEEN 1 AND 100 OR p_lease_ms NOT BETWEEN 1 AND 600000 THEN
    RAISE EXCEPTION 'Parámetros de cuota no válidos' USING ERRCODE = '22023';
  END IF;
  INSERT INTO biblib.catalogue_quota_buckets (provider, credential_scope, interval_ms, next_slot_at)
  VALUES (p_provider, p_scope, p_interval_ms, now_at) ON CONFLICT (provider, credential_scope) DO NOTHING;
  SELECT * INTO bucket FROM biblib.catalogue_quota_buckets AS b
  WHERE b.provider = p_provider AND b.credential_scope = p_scope FOR UPDATE;
  -- Limpieza acotada de reservas antiguas; nunca toca las vigentes.
  DELETE FROM biblib.catalogue_quota_reservations AS r WHERE r.ctid IN (
    SELECT old.ctid FROM biblib.catalogue_quota_reservations AS old
    WHERE old.provider = p_provider AND old.credential_scope = p_scope AND old.expires_at < now_at - interval '1 hour' LIMIT 100);
  IF bucket.cooldown_until > now_at THEN
    RETURN jsonb_build_object('state', 'cooldown', 'retryMs', ceil(extract(epoch FROM bucket.cooldown_until - now_at) * 1000)::bigint);
  END IF;
  SELECT count(*) INTO active FROM biblib.catalogue_quota_reservations AS r
  WHERE r.provider = p_provider AND r.credential_scope = p_scope AND r.owner_id IS NOT DISTINCT FROM p_owner
    AND r.purpose = p_purpose AND r.released_at IS NULL AND r.expires_at > now_at;
  IF active >= p_owner_cap THEN
    RETURN jsonb_build_object('state', 'busy', 'retryMs', p_interval_ms);
  END IF;
  slot := greatest(now_at, bucket.next_slot_at);
  IF slot > now_at + p_horizon_ms * interval '1 millisecond' THEN
    RETURN jsonb_build_object('state', 'wait', 'retryMs', greatest(1, ceil(extract(epoch FROM slot - now_at) * 1000) - p_horizon_ms)::bigint);
  END IF;
  granted := nextval('biblib.catalogue_fence_seq');
  UPDATE biblib.catalogue_quota_buckets AS b
  SET interval_ms = p_interval_ms, next_slot_at = slot + p_interval_ms * interval '1 millisecond', updated_at = now_at
  WHERE b.provider = p_provider AND b.credential_scope = p_scope;
  INSERT INTO biblib.catalogue_quota_reservations (provider, credential_scope, owner_id, purpose, fence, slot_at, expires_at)
  VALUES (p_provider, p_scope, p_owner, p_purpose, granted, slot, slot + p_lease_ms * interval '1 millisecond')
  RETURNING id INTO reservation;
  RETURN jsonb_build_object('state', 'reserved', 'reservationId', reservation, 'fence', granted::text, 'waitMs', ceil(extract(epoch FROM slot - now_at) * 1000)::bigint);
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  lease_ms integer := greatest(1000, least(coalesce(p_lease_ms, 60000), 300000));
  candidate biblib.library_jobs%ROWTYPE;
  claimed biblib.library_jobs%ROWTYPE;
  active boolean;
BEGIN
  FOR candidate IN
    SELECT * FROM biblib.library_jobs AS j
    WHERE (p_job_id IS NULL OR j.id = p_job_id) AND (p_owner IS NULL OR j.user_id = p_owner)
      AND j.state IN ('queued', 'running', 'waiting_retry') AND j.next_attempt_at <= now_at
      AND (j.state <> 'running' OR j.lease_until <= now_at)
    ORDER BY j.next_attempt_at, j.created_at
    LIMIT 10
    FOR UPDATE SKIP LOCKED
  LOOP
    active := biblib.account_is_active(candidate.user_id);
    -- Caducado, cuenta no activa o pasos que fallan una y otra vez: se cierra sin ejecutar.
    IF candidate.expires_at <= now_at OR NOT active OR candidate.attempts >= 10 THEN
      UPDATE biblib.library_jobs AS j
      SET state = CASE WHEN candidate.expires_at <= now_at OR NOT active THEN 'expired' ELSE 'failed' END,
        error_code = CASE WHEN candidate.expires_at <= now_at THEN 'JOB_EXPIRED' WHEN NOT active THEN 'ACCOUNT_INACTIVE' ELSE 'STEP_FAILED' END,
        lease_token = NULL, lease_until = NULL, version = gen_random_uuid(), finished_at = now_at, expires_at = now_at + interval '30 days', updated_at = now_at
      WHERE j.id = candidate.id;
      CONTINUE;
    END IF;
    UPDATE biblib.library_jobs AS j
    SET state = 'running', lease_token = gen_random_uuid(), lease_until = now_at + lease_ms * interval '1 millisecond',
      fencing_number = nextval('biblib.library_job_fence_seq'), attempts = j.attempts + 1, updated_at = now_at
    WHERE j.id = candidate.id
    RETURNING * INTO claimed;
    RETURN to_jsonb(claimed) || jsonb_build_object('fencing_number', claimed.fencing_number::text);
  END LOOP;
  RETURN NULL;
END;

DECLARE
  owner_id uuid := auth.uid();
  now_at timestamptz;
  job biblib.library_jobs%ROWTYPE;
  target text;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'library_job_control requiere una sesión' USING ERRCODE = '42501';
  END IF;
  IF p_action NOT IN ('pause', 'resume', 'cancel') THEN
    RAISE EXCEPTION 'Acción de trabajo no válida' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO job FROM biblib.library_jobs AS j WHERE j.id = p_job_id AND j.user_id = owner_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;
  now_at := clock_timestamp();
  IF job.state IN ('queued', 'running', 'waiting_retry', 'needs_review', 'paused') AND (job.expires_at <= now_at OR NOT biblib.account_is_active(owner_id)) THEN
    UPDATE biblib.library_jobs AS j
    SET state = 'expired', error_code = CASE WHEN job.expires_at <= now_at THEN 'JOB_EXPIRED' ELSE 'ACCOUNT_INACTIVE' END,
      lease_token = NULL, lease_until = NULL, version = gen_random_uuid(), finished_at = now_at, expires_at = now_at + interval '30 days', updated_at = now_at
    WHERE j.id = job.id;
    RETURN jsonb_build_object('status', 'expired', 'published', job.published_at IS NOT NULL);
  END IF;
  IF job.state = 'expired' THEN
    RETURN jsonb_build_object('status', 'expired', 'published', job.published_at IS NOT NULL);
  END IF;
  IF job.version <> p_expected_version THEN
    RETURN jsonb_build_object('status', 'conflict');
  END IF;
  target := CASE
    WHEN p_action = 'pause' AND job.state IN ('queued', 'running', 'waiting_retry') THEN 'paused'
    WHEN p_action = 'resume' AND job.state = 'paused' THEN 'queued'
    WHEN p_action = 'cancel' AND job.state IN ('queued', 'running', 'waiting_retry', 'needs_review', 'paused') THEN 'cancelled'
  END;
  IF target IS NULL THEN
    IF (p_action = 'pause' AND job.state = 'paused') OR (p_action = 'resume' AND job.state IN ('queued', 'running', 'waiting_retry')) OR (p_action = 'cancel' AND job.state = 'cancelled') THEN
      RETURN jsonb_build_object('status', 'ok', 'published', job.published_at IS NOT NULL);
    END IF;
    RETURN jsonb_build_object('status', 'conflict');
  END IF;
  UPDATE biblib.library_jobs AS j
  SET state = target, version = gen_random_uuid(), lease_token = NULL, lease_until = NULL,
    next_attempt_at = CASE WHEN target = 'queued' THEN now_at ELSE j.next_attempt_at END,
    error_code = CASE WHEN target = 'cancelled' THEN 'CANCELLED' ELSE j.error_code END,
    finished_at = CASE WHEN target = 'cancelled' THEN now_at ELSE j.finished_at END,
    expires_at = CASE WHEN target = 'cancelled' THEN now_at + interval '30 days' ELSE j.expires_at END,
    updated_at = now_at
  WHERE j.id = job.id;
  RETURN jsonb_build_object('status', 'ok', 'published', job.published_at IS NOT NULL);
END;

DECLARE
  owner_id uuid := auth.uid();
  now_at timestamptz := clock_timestamp();
  existing biblib.library_jobs%ROWTYPE;
  active_id uuid;
  created_id uuid;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'library_job_create requiere una sesión' USING ERRCODE = '42501';
  END IF;
  IF NOT biblib.account_is_active(owner_id) THEN
    RETURN jsonb_build_object('status', 'inactive');
  END IF;
  -- Serializa las altas del mismo dueño: clave, límite y trabajo de portadas activo.
  PERFORM pg_advisory_xact_lock(hashtextextended('biblib.library_jobs:' || owner_id::text, 0));
  SELECT * INTO existing FROM biblib.library_jobs AS j WHERE j.user_id = owner_id AND j.kind = p_kind AND j.idempotency_key = p_idempotency_key;
  IF FOUND THEN
    IF existing.input_digest <> p_input_digest THEN
      RETURN jsonb_build_object('status', 'conflict');
    END IF;
    RETURN jsonb_build_object('status', 'existing', 'id', existing.id);
  END IF;
  IF p_kind = 'import' AND NOT EXISTS (SELECT 1 FROM biblib.import_previews AS preview WHERE preview.id = p_preview_id AND preview.user_id = owner_id) THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;
  -- Resúmenes terminados fuera de su retención.
  DELETE FROM biblib.library_jobs AS j WHERE j.user_id = owner_id AND j.finished_at IS NOT NULL AND j.expires_at <= now_at;
  IF p_kind = 'covers' THEN
    SELECT j.id INTO active_id FROM biblib.library_jobs AS j
    WHERE j.user_id = owner_id AND j.kind = 'covers' AND j.state IN ('queued', 'running', 'waiting_retry', 'paused') LIMIT 1;
    IF FOUND THEN
      RETURN jsonb_build_object('status', 'busy', 'id', active_id);
    END IF;
  END IF;
  IF (SELECT count(*) FROM biblib.library_jobs AS j WHERE j.user_id = owner_id AND j.state IN ('queued', 'running', 'waiting_retry', 'paused')) >= 5 THEN
    RETURN jsonb_build_object('status', 'limit');
  END IF;
  INSERT INTO biblib.library_jobs (user_id, kind, contract_version, idempotency_key, input_digest, preview_id, expected_revision, phase, next_attempt_at, expires_at)
  VALUES (owner_id, p_kind, 1, p_idempotency_key, p_input_digest, p_preview_id, p_expected_revision,
    CASE WHEN p_kind = 'import' THEN 'publish' ELSE 'covers' END, now_at, now_at + interval '7 days')
  RETURNING id INTO created_id;
  RETURN jsonb_build_object('status', 'created', 'id', created_id);
END;

DECLARE
  job record;
BEGIN
  SELECT j.user_id, j.state, j.lease_token, j.fencing_number, j.lease_until INTO job
  FROM biblib.library_jobs AS j WHERE j.id = p_job_id FOR UPDATE;
  IF NOT FOUND OR job.state <> 'running' OR job.lease_token IS DISTINCT FROM p_lease_token OR job.fencing_number <> p_fencing OR job.lease_until <= clock_timestamp() THEN
    RAISE EXCEPTION 'El lease del trabajo ya no es válido' USING ERRCODE = 'BJ001';
  END IF;
  IF NOT biblib.account_is_active(job.user_id) THEN
    RAISE EXCEPTION 'La cuenta del trabajo no está activa' USING ERRCODE = 'BJ002';
  END IF;
  RETURN job.user_id;
END;

DECLARE
  now_at timestamptz := clock_timestamp();
BEGIN
  UPDATE biblib.library_jobs AS j
  SET lease_until = now_at + greatest(1000, least(coalesce(p_lease_ms, 60000), 300000)) * interval '1 millisecond', updated_at = now_at
  WHERE j.id = p_job_id AND j.state = 'running' AND j.lease_token = p_lease_token AND j.fencing_number = p_fencing
    AND j.lease_until > now_at AND biblib.account_is_active(j.user_id);
  RETURN FOUND;
END;

DECLARE
  owner_id uuid := auth.uid();
  now_at timestamptz := clock_timestamp();
  captured uuid;
  new_id uuid;
  book_total integer;
  shelf_total integer;
  shelf_chunks integer;
  chunk_total integer;
  byte_total bigint;
  final_digest text;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'library_snapshot_capture requiere una sesión' USING ERRCODE = '42501';
  END IF;
  IF p_reason NOT IN ('import.replace', 'snapshot.restore') THEN
    RAISE EXCEPTION 'Motivo de captura no válido' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM biblib.library_operations AS o WHERE o.id = p_operation_id AND o.user_id = owner_id AND o.created_at = now()) THEN
    RAISE EXCEPTION 'La captura exige la operación de esta misma transacción' USING ERRCODE = '42501';
  END IF;
  IF NOT biblib.account_is_active(owner_id) THEN
    RAISE EXCEPTION 'La cuenta no admite versiones nuevas' USING ERRCODE = 'BS002';
  END IF;
  -- Bajo el bloqueo de colección: la revisión capturada es la que la operación va a sustituir.
  captured := biblib.lock_library();
  -- Las versiones vencidas ya no se muestran ni se restauran: se retiran al capturar.
  DELETE FROM biblib.library_snapshots AS s WHERE s.user_id = owner_id AND s.expires_at <= now_at;
  IF (SELECT count(*) FROM biblib.library_snapshots AS s WHERE s.user_id = owner_id) >= 10 THEN
    RAISE EXCEPTION 'Cuota de versiones anteriores agotada' USING ERRCODE = 'BS001';
  END IF;
  SELECT count(*) INTO book_total FROM biblib.books AS b WHERE b.user_id = owner_id;
  SELECT count(*) INTO shelf_total FROM biblib.shelves AS sh WHERE sh.user_id = owner_id;
  IF book_total > 10000 OR shelf_total > 1000 THEN
    RAISE EXCEPTION 'Colección demasiado grande para guardar una versión anterior' USING ERRCODE = 'BS003';
  END IF;
  INSERT INTO biblib.library_snapshots AS s (user_id, source_operation_id, reason, captured_revision, schema_version, state, expires_at, created_at)
  VALUES (owner_id, p_operation_id, p_reason, captured, 1, 'capturing', now_at + interval '30 days', now_at)
  RETURNING s.id INTO new_id;
  shelf_chunks := (shelf_total + 199) / 200;
  INSERT INTO biblib.library_snapshot_chunks (snapshot_id, user_id, seq, kind, item_count, payload, digest)
  SELECT new_id, owner_id, grouped.seq, grouped.kind, grouped.n, grouped.payload, encode(sha256(convert_to(grouped.payload::text, 'UTF8')), 'hex')
  FROM (
    SELECT (ranked.rn / 200)::integer AS seq, 'shelves'::text AS kind, count(*)::integer AS n, jsonb_agg(ranked.item ORDER BY ranked.rn) AS payload
    FROM (
      SELECT row_number() OVER (ORDER BY sh.created_at, sh.id) - 1 AS rn,
        jsonb_build_object('id', sh.id, 'title', sh.title, 'is_default', sh.is_default, 'created_at', sh.created_at) AS item
      FROM biblib.shelves AS sh WHERE sh.user_id = owner_id
    ) AS ranked
    GROUP BY ranked.rn / 200
    UNION ALL
    SELECT shelf_chunks + (ranked.rn / 200)::integer, 'books', count(*)::integer, jsonb_agg(ranked.item ORDER BY ranked.rn)
    FROM (
      SELECT row_number() OVER (ORDER BY b.id) - 1 AS rn,
        jsonb_build_object('id', b.id, 'isbn', b.isbn, 'title', b.title, 'subtitle', b.subtitle, 'authors', b.authors, 'publishers', b.publishers,
          'catalogue', b.catalogue, 'number_of_pages', b.number_of_pages, 'publish_date', b.publish_date, 'cover_small', b.cover_small,
          'cover_medium', b.cover_medium, 'cover_large', b.cover_large, 'status', b.status, 'shelf_id', b.shelf_id, 'created_at', b.created_at) AS item
      FROM biblib.books AS b WHERE b.user_id = owner_id
    ) AS ranked
    GROUP BY ranked.rn / 200
  ) AS grouped;
  SELECT count(*)::integer, coalesce(sum(octet_length(c.payload::text)), 0),
    encode(sha256(convert_to(concat_ws('|', 'biblib.snapshot.v1', book_total, shelf_total, coalesce(string_agg(c.digest, '' ORDER BY c.seq), '')), 'UTF8')), 'hex')
  INTO chunk_total, byte_total, final_digest
  FROM biblib.library_snapshot_chunks AS c WHERE c.snapshot_id = new_id;
  UPDATE biblib.library_snapshots AS s
  SET state = 'ready', digest = final_digest,
    counts = jsonb_build_object('books', book_total, 'shelves', shelf_total, 'chunks', chunk_total, 'bytes', byte_total)
  WHERE s.id = new_id;
  RETURN jsonb_build_object('id', new_id, 'digest', final_digest, 'books', book_total, 'shelves', shelf_total, 'chunks', chunk_total);
END;

DECLARE
  owner_id uuid := auth.uid();
  current_version uuid;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'library_snapshot_delete requiere una sesión' USING ERRCODE = '42501';
  END IF;
  PERFORM biblib.lock_library();
  SELECT s.version INTO current_version FROM biblib.library_snapshots AS s WHERE s.id = p_snapshot_id AND s.user_id = owner_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN 'not_found';
  END IF;
  IF current_version <> p_expected_version THEN
    RETURN 'conflict';
  END IF;
  DELETE FROM biblib.library_snapshots AS s WHERE s.id = p_snapshot_id AND s.user_id = owner_id;
  RETURN 'deleted';
END;

DECLARE
  owner_id uuid := auth.uid();
  found uuid[];
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'library_snapshot_foreign_ids requiere una sesión' USING ERRCODE = '42501';
  END IF;
  SELECT coalesce(array_agg(DISTINCT entry.id ORDER BY entry.id), '{}'::uuid[]) INTO found
  FROM (
    SELECT c.kind, (item->>'id')::uuid AS id
    FROM biblib.library_snapshot_chunks AS c CROSS JOIN LATERAL jsonb_array_elements(c.payload) AS item
    WHERE c.snapshot_id = p_snapshot_id AND c.user_id = owner_id
  ) AS entry
  WHERE (entry.kind = 'books' AND EXISTS (SELECT 1 FROM biblib.books AS b WHERE b.id = entry.id AND b.user_id <> owner_id))
    OR (entry.kind = 'shelves' AND EXISTS (SELECT 1 FROM biblib.shelves AS sh WHERE sh.id = entry.id AND sh.user_id <> owner_id));
  RETURN found;
END;

DECLARE
  removed integer;
BEGIN
  DELETE FROM biblib.library_snapshots AS s
  WHERE s.id IN (SELECT e.id FROM biblib.library_snapshots AS e WHERE e.expires_at <= clock_timestamp() ORDER BY e.expires_at LIMIT greatest(1, least(coalesce(p_limit, 100), 1000)));
  GET DIAGNOSTICS removed = ROW_COUNT;
  RETURN removed;
END;

DECLARE
  owner_id uuid := auth.uid();
  current_revision uuid;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'lock_library requiere una sesión' USING ERRCODE = '42501';
  END IF;
  INSERT INTO biblib.library_state (user_id) VALUES (owner_id) ON CONFLICT (user_id) DO NOTHING;
  SELECT state.revision INTO current_revision FROM biblib.library_state AS state WHERE state.user_id = owner_id FOR UPDATE;
  RETURN current_revision;
END;

BEGIN
  NEW.version := gen_random_uuid();
  RETURN NEW;
END;

DECLARE
  owners uuid[];
BEGIN
  IF TG_OP = 'INSERT' THEN
    owners := ARRAY[NEW.user_id];
  ELSIF TG_OP = 'DELETE' THEN
    owners := ARRAY[OLD.user_id];
  ELSE
    owners := ARRAY[NEW.user_id, OLD.user_id];
  END IF;
  INSERT INTO biblib.library_state AS state (user_id, rotated_xact)
  SELECT DISTINCT owner_id, pg_current_xact_id() FROM unnest(owners) AS owner_id
  WHERE EXISTS (SELECT 1 FROM auth.users AS account WHERE account.id = owner_id)
  ON CONFLICT (user_id) DO UPDATE
    SET revision = gen_random_uuid(), rotated_xact = excluded.rotated_xact, updated_at = now()
    WHERE state.rotated_xact IS DISTINCT FROM excluded.rotated_xact;
  RETURN NULL;
END;
